CREATE TABLE "Artikel" (
    "ArtikelID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Bezeichnung" VARCHAR(100) NOT NULL,
    "Bestand" INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT "pk_Artikel" PRIMARY KEY ("ArtikelID"),
    CONSTRAINT "uq_Artikel_Bezeichnung" UNIQUE ("Bezeichnung"),
    CONSTRAINT "ck_Artikel_Bezeichnung_nicht_leer"
        CHECK (btrim("Bezeichnung") <> ''),
    CONSTRAINT "ck_Artikel_Bestand_nicht_negativ"
        CHECK ("Bestand" >= 0)
);

CREATE TABLE "Mitarbeiter" (
    "MitarbeiterID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "Name" VARCHAR(100) NOT NULL,
    "Abteilung" VARCHAR(100),
    CONSTRAINT "pk_Mitarbeiter" PRIMARY KEY ("MitarbeiterID"),
    CONSTRAINT "ck_Mitarbeiter_Name_nicht_leer"
        CHECK (btrim("Name") <> '')
);

CREATE TABLE "Lagerbewegung" (
    "BewegungsID" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "ArtikelID" INTEGER NOT NULL,
    "MitarbeiterID" INTEGER NOT NULL,
    "Menge" INTEGER NOT NULL,
    "Bewegungsart" VARCHAR(20) NOT NULL,
    "Bewegungszeitpunkt" TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT "pk_Lagerbewegung" PRIMARY KEY ("BewegungsID"),
    CONSTRAINT "fk_Lagerbewegung_Artikel"
        FOREIGN KEY ("ArtikelID") REFERENCES "Artikel" ("ArtikelID")
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT "fk_Lagerbewegung_Mitarbeiter"
        FOREIGN KEY ("MitarbeiterID") REFERENCES "Mitarbeiter" ("MitarbeiterID")
        ON UPDATE NO ACTION ON DELETE NO ACTION,
    CONSTRAINT "ck_Lagerbewegung_Menge_positiv"
        CHECK ("Menge" > 0),
    CONSTRAINT "ck_Lagerbewegung_Bewegungsart"
        CHECK ("Bewegungsart" IN ('Eingang', 'Ausgang'))
);

CREATE INDEX "idx_Lagerbewegung_ArtikelID" ON "Lagerbewegung" ("ArtikelID");
CREATE INDEX "idx_Lagerbewegung_MitarbeiterID" ON "Lagerbewegung" ("MitarbeiterID");